# ---------------------------------------------------------------- materials
MATS = {}


def material(name, color, emit=0.0, rough=0.75, alpha=1.0):
    mat = bpy.data.materials.new(name)
    mat.diffuse_color = color[:3] + (alpha,)
    try:
        mat.use_nodes = True
    except Exception:
        pass
    bsdf = mat.node_tree.nodes.get("Principled BSDF") if getattr(mat, "node_tree", None) else None
    if bsdf is not None:
        bsdf.inputs["Base Color"].default_value = color
        bsdf.inputs["Roughness"].default_value = rough
        if emit:
            bsdf.inputs["Emission Color"].default_value = color
            bsdf.inputs["Emission Strength"].default_value = emit
        if alpha < 1.0:
            bsdf.inputs["Alpha"].default_value = alpha
            for attr, value in (("surface_render_method", "BLENDED"), ("blend_method", "BLEND")):
                try:
                    setattr(mat, attr, value)
                except Exception:
                    pass
    return mat


def mat_for(key, color, variant="normal", emit=0.0):
    """Material per (key, variant): normal, ghost (25% opacity) or glow (highlighted)."""
    k = (key, variant)
    if k not in MATS:
        if variant == "ghost":
            MATS[k] = material(key + "_ghost", color, 0.0, 0.9, GHOST_ALPHA)
        elif variant == "glow":
            MATS[k] = material(key + "_glow", color, max(emit, 0.0) + 0.45, 0.5)
        else:
            MATS[k] = material(key, color, emit)
    return MATS[k]


def set_color(mat, color, frame=None):
    mat.diffuse_color = color
    bsdf = mat.node_tree.nodes.get("Principled BSDF") if getattr(mat, "node_tree", None) else None
    targets = [] if bsdf is None else [bsdf.inputs["Base Color"], bsdf.inputs["Emission Color"]]
    for inp in targets:
        inp.default_value = color
    if frame is not None:
        mat.keyframe_insert("diffuse_color", frame=frame)
        for inp in targets:
            inp.keyframe_insert("default_value", frame=frame)


# ---------------------------------------------------------------- primitives
REGISTRY = []   # (object, group, base material key, base colour, emit) for per-shot ghost / glow / hide


def register(obj, group, key, color, emit=0.0):
    obj["grp"] = group
    REGISTRY.append((obj, group, key, color, emit))
    return obj


def link(obj, mat=None):
    bpy.context.scene.collection.objects.link(obj) if obj.name not in bpy.context.scene.collection.objects else None
    if mat is not None:
        obj.data.materials.append(mat)
    return obj


def cylinder(name, r, depth, loc, rot=(0, 0, 0), mat=None, vertices=32):
    bpy.ops.mesh.primitive_cylinder_add(radius=r, depth=depth, location=loc, rotation=rot, vertices=vertices)
    obj = bpy.context.active_object
    obj.name = name
    if mat is not None:
        obj.data.materials.append(mat)
    bpy.ops.object.shade_smooth()
    return obj


def sphere(name, r, loc, mat=None, scale=(1, 1, 1)):
    bpy.ops.mesh.primitive_uv_sphere_add(radius=r, location=loc, segments=24, ring_count=12)
    obj = bpy.context.active_object
    obj.name, obj.scale = name, scale
    if mat is not None:
        obj.data.materials.append(mat)
    bpy.ops.object.shade_smooth()
    return obj


def box(name, size, loc, mat=None):
    bpy.ops.mesh.primitive_cube_add(size=1, location=loc)
    obj = bpy.context.active_object
    obj.name, obj.scale = name, size
    if mat is not None:
        obj.data.materials.append(mat)
    return obj


def cone(name, r1, r2, depth, loc, rot=(0, 0, 0), mat=None, vertices=16):
    bpy.ops.mesh.primitive_cone_add(radius1=r1, radius2=r2, depth=depth, location=loc, rotation=rot, vertices=vertices)
    obj = bpy.context.active_object
    obj.name = name
    if mat is not None:
        obj.data.materials.append(mat)
    return obj


def torus(name, major, minor, loc, mat=None):
    bpy.ops.mesh.primitive_torus_add(major_radius=major, minor_radius=minor, location=loc, major_segments=48,
                                     minor_segments=8)
    obj = bpy.context.active_object
    obj.name = name
    if mat is not None:
        obj.data.materials.append(mat)
    return obj


def segment(name, a, b, r, mat=None, vertices=12):
    """Cylinder from point a to point b."""
    va, vb = Vector(a), Vector(b)
    v = vb - va
    obj = cylinder(name, r, max(v.length, 1e-4), tuple((va + vb) / 2), mat=mat, vertices=vertices)
    obj.rotation_mode = "QUATERNION"
    obj.rotation_quaternion = v.to_track_quat("Z", "Y")
    return obj


def text(name, body, loc, size, mat, camera=None, align="CENTER", align_y=None):
    curve = bpy.data.curves.new(name, "FONT")
    curve.body, curve.size, curve.align_x = body, size, align
    if label_font() is not None:
        curve.font = label_font()
    if align_y:
        try:
            curve.align_y = align_y
        except Exception:
            pass
    obj = bpy.data.objects.new(name, curve)
    obj.location = loc
    link(obj, mat)
    obj.visible_shadow = False
    if camera is not None:
        c = obj.constraints.new("TRACK_TO")
        c.target, c.track_axis, c.up_axis = camera, "TRACK_Z", "UP_Y"
    return obj


def rounded_rect_mesh(name, x0, y0, x1, y1, radius, z=0.0, steps=6):
    """A flat rounded rectangle (a pill when radius = half height), one n-gon face."""
    radius = max(0.0, min(radius, (x1 - x0) / 2, (y1 - y0) / 2))
    centres = ((x1 - radius, y1 - radius, 0), (x0 + radius, y1 - radius, 90), (x0 + radius, y0 + radius, 180),
               (x1 - radius, y0 + radius, 270))
    verts = []
    for cx, cy, start in centres:
        for j in range(steps + 1):
            a = math.radians(start + 90 * j / steps)
            verts.append((cx + radius * math.cos(a), cy + radius * math.sin(a), z))
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, [], [list(range(len(verts)))])
    me.update()
    return me


def show(obj, visible):
    obj.hide_render = not visible
    obj.hide_viewport = not visible


