def build_equipment_legacy(e, mat):
    x, y, _ = e["position"]
    d, h, length = e["dims"]
    shape = e["shape"]
    if shape in ("vertical_vessel", "column"):
        skirt = 0.8
        cylinder(e["id"] + "_shell", d / 2, h, (x, y, skirt + h / 2), mat=mat)
        sphere(e["id"] + "_top", d / 2, (x, y, skirt + h), mat, (1, 1, 0.45))
        sphere(e["id"] + "_bottom", d / 2, (x, y, skirt), mat, (1, 1, 0.45))
        cylinder(e["id"] + "_skirt", d / 2 * 0.9, skirt, (x, y, skirt / 2), mat=mat)
        if e.get("agitator"):
            cylinder(e["id"] + "_agitator_motor", 0.3, 0.8, (x, y, skirt + h + d * 0.22 + 0.4), mat=mat)
    elif shape == "horizontal_exchanger":
        z = e["nozzle_z"]
        cylinder(e["id"] + "_shell", d / 2, length, (x, y, z), (0, math.pi / 2, 0), mat)
        for s in (-1, 1):
            cylinder(e["id"] + "_head%d" % s, d / 2 * 1.1, 0.4, (x + s * (length / 2 + 0.2), y, z), (0, math.pi / 2, 0), mat)
            box(e["id"] + "_support%d" % s, (0.3, d, z), (x + s * length / 3, y, z / 2), mat)
    elif shape == "header":
        z = e["nozzle_z"]
        cylinder(e["id"] + "_header", d / 2, length, (x, y, z), (0, math.pi / 2, 0), mat)
        for s in (-1, 1):
            box(e["id"] + "_support%d" % s, (0.3, 0.3, z), (x + s * length / 3, y, z / 2), mat)
    elif shape == "compressor":
        box(e["id"] + "_skid", (length + 1.2, d + 0.4, 0.3), (x, y, 0.15), mat)
        cylinder(e["id"] + "_casing", d / 2, length * 0.6, (x - length * 0.2, y, 0.3 + d / 2), (0, math.pi / 2, 0), mat)
        box(e["id"] + "_driver", (length * 0.4, d * 0.8, d * 0.8), (x + length * 0.4, y, 0.3 + d * 0.4), mat)
    else:
        box(e["id"] + "_generic", (d, d, h), (x, y, h / 2), mat)


def build_pipe_legacy(p, mat, arrow_mat):
    curve = bpy.data.curves.new(p["id"] + "_curve", "CURVE")
    curve.dimensions, curve.bevel_depth, curve.bevel_resolution = "3D", 0.09, 3
    spline = curve.splines.new("POLY")
    spline.points.add(len(p["points"]) - 1)
    for i, pt in enumerate(p["points"]):
        spline.points[i].co = (pt[0], pt[1], pt[2], 1.0)
    obj = link(bpy.data.objects.new(p["id"], curve), mat)
    obj["stream"], obj["direction_basis"], obj["geometry"] = p["id"], p["direction_basis"], p["route_status"]
    if not p["directed"]:
        return
    pts = p["points"]
    seg = max(range(len(pts) - 1), key=lambda i: math.dist(pts[i], pts[i + 1]))
    a, b = pts[seg], pts[seg + 1]
    mid = tuple((a[k] + b[k]) / 2 for k in range(3))
    dx, dy, dz = (b[k] - a[k] for k in range(3))
    n = math.sqrt(dx * dx + dy * dy + dz * dz) or 1.0
    bpy.ops.mesh.primitive_cone_add(radius1=0.22, depth=0.5, location=mid,
                                    rotation=(0, math.acos(max(-1.0, min(1.0, dz / n))), math.atan2(dy, dx)))
    c = bpy.context.active_object
    c.name = p["id"] + "_arrow"
    c.data.materials.append(arrow_mat)


# ---------------------------------------------------------------- redesigned builders (placeholder sizes, real types)
def part(obj, unit, kind, key=None, color=None):
    color = color or EQUIPMENT_COLORS.get(kind, EQUIPMENT_COLORS["unknown"])
    key = key or "eq_" + kind
    obj.data.materials.clear()
    obj.data.materials.append(mat_for(key, color))
    obj["asset"] = unit
    return register(obj, "unit:" + unit, key, color)


def steel(obj, unit):
    return part(obj, unit, "steel", "steel", COLORS["steel"])


def build_nozzles(e):
    """Short radial nozzle with a flange where each stream meets the shell (placeholder positions)."""
    x, y, _ = e["position"]
    r = e["dims"][0] / 2
    for k, nz in enumerate(e.get("nozzles", [])):
        px, py, pz = nz["at"]
        if e["shape"] in ("vertical_vessel", "column"):
            dx, dy = px - x, py - y
            n = math.hypot(dx, dy) or 1.0
            a = (x + dx / n * r * 0.95, y + dy / n * r * 0.95, pz)
            steel(segment("%s_nozzle%d" % (e["id"], k), a, (px, py, pz), 0.11), e["id"])
            steel(segment("%s_flange%d" % (e["id"], k), (px - dx / n * 0.03, py - dy / n * 0.03, pz),
                          (px + dx / n * 0.03, py + dy / n * 0.03, pz), 0.18), e["id"])


def build_equipment_v2(e):
    x, y, _ = e["position"]
    d, h, length = e["dims"]
    r = d / 2
    uid, kind, shape = e["id"], e["kind"], e["shape"]
    if shape in ("vertical_vessel", "column"):
        z0 = 0.8 if (e.get("agitator") or shape == "column") else 1.0
        part(cylinder(uid + "_shell", r, h, (x, y, z0 + h / 2)), uid, kind)
        part(sphere(uid + "_top", r, (x, y, z0 + h), scale=(1, 1, 0.5)), uid, kind)       # 2:1 ellipsoidal heads
        part(sphere(uid + "_bottom", r, (x, y, z0), scale=(1, 1, 0.5)), uid, kind)
        if z0 == 0.8:
            steel(cylinder(uid + "_skirt", r * 0.97, z0, (x, y, z0 / 2)), uid)
        else:
            for k in range(4):
                a = math.radians(45 + 90 * k)
                steel(cylinder("%s_leg%d" % (uid, k), 0.08, z0, (x + r * 0.8 * math.cos(a), y + r * 0.8 * math.sin(a), z0 / 2),
                               vertices=12), uid)
        if e.get("agitator"):
            steel(cylinder(uid + "_agitator_drive", 0.22, 0.5, (x, y, z0 + h + r * 0.5 + 0.25)), uid)
            part(cylinder(uid + "_agitator_motor", 0.32, 0.7, (x, y, z0 + h + r * 0.5 + 0.85)), uid, "compressor",
                 "eq_motor", EQUIPMENT_COLORS["compressor"])
        if shape == "column":
            for k, zp in enumerate([z for z in (3.0, 6.0, 9.0, 12.0) if z < z0 + h - 0.5]):
                steel(cylinder("%s_platform%d" % (uid, k), r + 0.75, 0.07, (x, y, zp)), uid)
                part(torus("%s_rail%d" % (uid, k), r + 0.72, 0.025, (x, y, zp + 1.0)), uid, "platform", "platform",
                     COLORS["platform"])
            la = math.radians(60)
            for side in (-1, 1):
                off = (math.cos(la + side * 0.12) * (r + 0.4), math.sin(la + side * 0.12) * (r + 0.4))
                part(segment("%s_ladder%d" % (uid, side), (x + off[0], y + off[1], 0.2), (x + off[0], y + off[1], z0 + h),
                             0.025, vertices=6), uid, "platform", "platform", COLORS["platform"])
        build_nozzles(e)
    elif shape == "horizontal_exchanger":
        z = e["nozzle_z"]
        part(cylinder(uid + "_shell", r, length, (x, y, z), (0, math.pi / 2, 0)), uid, kind)
        part(cylinder(uid + "_channel", r * 1.12, 0.7, (x - length / 2 - 0.35, y, z), (0, math.pi / 2, 0)), uid, kind)
        part(sphere(uid + "_channel_cover", r * 1.12, (x - length / 2 - 0.7, y, z), scale=(0.35, 1, 1)), uid, kind)
        part(sphere(uid + "_rear_head", r, (x + length / 2, y, z), scale=(0.5, 1, 1)), uid, kind)
        for s in (-1, 1):
            steel(box("%s_saddle%d" % (uid, s), (0.35, d * 0.9, z - r * 0.6), (x + s * length / 3, y, (z - r * 0.6) / 2)), uid)
        for k, xo in enumerate((-length / 3, length / 3)):
            steel(cylinder("%s_nozzle%d" % (uid, k), 0.12, 0.5, (x + xo, y, z + r + 0.2)), uid)
    elif shape == "header":
        z = e["nozzle_z"]
        part(cylinder(uid + "_header", r, length, (x, y, z), (0, math.pi / 2, 0)), uid, kind)
        for s in (-1, 1):
            part(sphere("%s_cap%d" % (uid, s), r, (x + s * length / 2, y, z), scale=(0.5, 1, 1)), uid, kind)
            steel(box("%s_support%d" % (uid, s), (0.25, 0.25, z - r), (x + s * length / 3, y, (z - r) / 2)), uid)
        for k, nz in enumerate(e.get("nozzles", [])):   # branch take-offs up to each connection
            px, py, pz = nz["at"]
            steel(segment("%s_branch%d" % (uid, k), (px, y, z), (px, py, pz), 0.1), uid)
    elif shape == "compressor":
        base_w = length + 1.2
        steel(box(uid + "_baseplate", (base_w, d + 0.4, 0.25), (x, y, 0.125)), uid)
        cz = 0.25 + r
        part(cylinder(uid + "_casing", r, 0.9, (x - 0.7, y, cz), (0, math.pi / 2, 0)), uid, kind)
        part(torus(uid + "_volute", r * 0.95, 0.22, (x - 0.7, y, cz)), uid, kind)
        bpy.context.active_object.rotation_euler = (0, math.pi / 2, 0)
        steel(cylinder(uid + "_suction", 0.18, 0.6, (x - 0.7, y, cz + r + 0.3)), uid)
        steel(cylinder(uid + "_coupling", 0.12, 0.5, (x, y, cz), (0, math.pi / 2, 0)), uid)
        part(cylinder(uid + "_motor", r * 0.7, 1.3, (x + 0.85, y, 0.25 + r * 0.7), (0, math.pi / 2, 0)), uid,
             "compressor", "eq_motor", EQUIPMENT_COLORS["compressor"])
        part(sphere(uid + "_motor_end", r * 0.7, (x + 1.5, y, 0.25 + r * 0.7), scale=(0.3, 1, 1)), uid,
             "compressor", "eq_motor", EQUIPMENT_COLORS["compressor"])
    else:
        part(box(uid + "_generic", (d, d, h), (x, y, h / 2)), uid, "unknown")


def poly_curve(name, points, bevel):
    curve = bpy.data.curves.new(name + "_curve", "CURVE")
    curve.dimensions, curve.bevel_depth, curve.bevel_resolution = "3D", bevel, 3
    spline = curve.splines.new("POLY")
    spline.points.add(len(points) - 1)
    for i, pt in enumerate(points):
        spline.points[i].co = (pt[0], pt[1], pt[2], 1.0)
    return link(bpy.data.objects.new(name, curve))


def chevrons(name, points, color, group, spacing=2.2, size=0.28):
    """Flat arrowheads along a polyline, pointing in flow direction (stills); the video can animate their offset."""
    out = []
    lengths = [math.dist(points[i], points[i + 1]) for i in range(len(points) - 1)]
    total = sum(lengths)
    t = 0.8
    k = 0
    light = tuple(min(1.0, c * 0.6 + 0.4) for c in color[:3]) + (1,)
    while t < total - 0.5:
        run = 0.0
        for i, L in enumerate(lengths):
            if run + L >= t and L > 0:
                f = (t - run) / L
                a, b = Vector(points[i]), Vector(points[i + 1])
                pos = a + (b - a) * f
                c = cone("%s_chev%d" % (name, k), size, 0.0, size * 1.6, tuple(pos), vertices=3)
                c.rotation_mode = "QUATERNION"
                c.rotation_quaternion = (b - a).to_track_quat("Z", "Y")
                c.scale = (1.0, 0.35, 1.0)
                c.visible_shadow = False
                c.data.materials.append(mat_for("chev_" + group, light, emit=1.2))
                register(c, "chev:" + group, "chev_" + group, light, 1.2)
                out.append(c)
                k += 1
                break
            run += L
        t += spacing
    return out


def build_pipe_v2(p):
    color = SERVICE_COLORS.get(p["service"], SERVICE_COLORS["process"])
    obj = poly_curve(p["id"], p["points"], 0.10 if p["service"] != "liquid_product" else 0.085)
    obj.data.materials.append(mat_for("svc_" + p["service"], color, emit=0.15))
    obj["stream"], obj["service"], obj["geometry"] = p["id"], p["service"], p["route_status"]
    register(obj, "pipe:" + p["id"], "svc_" + p["service"], color, 0.15)
    if p["directed"]:
        chevrons(p["id"], p["points"], color, p["id"])


def build_utility(u):
    color = SERVICE_COLORS.get(u["service"], SERVICE_COLORS["process"])
    obj = poly_curve(u["id"], u["points"], 0.075)
    obj.data.materials.append(mat_for("svc_" + u["service"], color, emit=0.2))
    obj["inferred"] = u["basis"]
    register(obj, "util:" + u["id"], "svc_" + u["service"], color, 0.2)
    post = cylinder(u["id"] + "_post", 0.12, 0.6, (u["post"][0], u["post"][1], 0.3), vertices=12)
    post.data.materials.append(mat_for("svc_" + u["service"], color, emit=0.2))
    register(post, "util:" + u["id"], "svc_" + u["service"], color, 0.2)
    pts = u["points"] if u["role"] == "return" else list(reversed(u["points"]))   # supply and steam flow to the unit
    chevrons(u["id"], pts, color, u["id"], spacing=1.2, size=0.2)


def build_valve(v):
    """Control-valve symbol: a bowtie body and an actuator. Position is a placeholder on the line."""
    x, y, z = v["position"]
    axis = {"x": (1, 0, 0), "y": (0, 1, 0), "z": (0, 0, 1)}[v["axis"]]
    a = Vector((x, y, z))
    ax = Vector(axis)
    grp = "valve:" + v["tag"]
    for s in (-1, 1):
        c = cone("%s_body%d" % (v["tag"], s), 0.2, 0.02, 0.26, tuple(a + ax * 0.13 * s))
        c.rotation_mode = "QUATERNION"
        c.rotation_quaternion = (ax * -s).to_track_quat("Z", "Y")
        c.data.materials.append(mat_for("valve", COLORS["valve"]))
        register(c, grp, "valve", COLORS["valve"])
    stem_dir = Vector((0, 0, 1)) if v["axis"] != "z" else Vector((0, -1, 0))
    st = segment(v["tag"] + "_stem", tuple(a), tuple(a + stem_dir * 0.32), 0.03, vertices=8)
    st.data.materials.append(mat_for("valve", COLORS["valve"]))
    register(st, grp, "valve", COLORS["valve"])
    act = sphere(v["tag"] + "_actuator", 0.17, tuple(a + stem_dir * 0.42), scale=(1, 1, 0.55) if v["axis"] != "z" else (1, 0.55, 1))
    act.data.materials.append(mat_for("actuator", COLORS["actuator"]))
    register(act, grp, "actuator", COLORS["actuator"])


def ground_material():
    mat = material("ground", COLORS["ground"], 0.0, 0.95)
    try:
        nt = mat.node_tree
        bsdf = nt.nodes.get("Principled BSDF")
        tex = nt.nodes.new("ShaderNodeTexBrick")
        tex.offset, tex.squash = 0.0, 1.0
        tex.inputs["Color1"].default_value = COLORS["ground"]
        tex.inputs["Color2"].default_value = COLORS["ground"]
        tex.inputs["Mortar"].default_value = (0.30, 0.31, 0.33, 1)
        tex.inputs["Scale"].default_value = 0.5
        tex.inputs["Mortar Size"].default_value = 0.012
        tex.inputs["Brick Width"].default_value = 1.0
        tex.inputs["Row Height"].default_value = 1.0
        geo = nt.nodes.new("ShaderNodeNewGeometry")   # world position: a 2 m grid whatever the plane's size
        nt.links.new(geo.outputs["Position"], tex.inputs["Vector"])
        nt.links.new(tex.outputs["Color"], bsdf.inputs["Base Color"])
    except Exception as exc:
        print("GROUND GRID UNAVAILABLE", exc)
    return mat


# ---------------------------------------------------------------- labels (3D pills on leaders)
LABELS = {}


def make_label(spec, cam, mats):
    lid, kind = spec["id"], spec["kind"]
    if LEGACY:
        size = {"unit": 0.45, "boundary": 0.3, "tag": 0.2}.get(kind, 0.25)
        obj = text("label_" + lid, spec.get("legacy_body", spec["body"]), tuple(spec.get("legacy_location", spec["anchor"])),
                   size, mats["text"], cam)
        LABELS[lid] = {"spec": spec, "obj": obj, "plate": None, "leader": None}
        return
    obj = text("label_" + lid, spec["body"], (0, 0, 0), 1.0, mats["text"], align_y="CENTER")
    rot = obj.constraints.new("COPY_ROTATION")
    rot.target = cam
    plate = bpy.data.objects.new("plate_" + lid, rounded_rect_mesh("plate_" + lid, -1, -0.5, 1, 0.5, 0.5))
    link(plate)
    plate.data.materials.append(mats["loto_plate"] if kind == "loto" else mats["plate"])
    plate.parent = obj
    plate.visible_shadow = False
    bpy.ops.mesh.primitive_cone_add(radius1=1.0, radius2=LABEL_DEPTH, depth=1.0, vertices=8, location=(0, 0, 0))
    leader = bpy.context.active_object
    leader.name = "leader_" + lid
    leader.data.materials.append(mats["leader"])
    leader.rotation_mode = "QUATERNION"
    leader.visible_shadow = False
    LABELS[lid] = {"spec": spec, "obj": obj, "plate": plate, "leader": leader}


def parts(L):
    return [o for o in (L["obj"], L["plate"], L["leader"]) if o is not None]


def main(argv):
    out = os.path.abspath(argv[argv.index("--out") + 1] if "--out" in argv else "renders")
    animation = "--animation" in argv
    os.makedirs(out, exist_ok=True)
    bpy.ops.wm.read_factory_settings(use_empty=True)
    scene = bpy.context.scene
    mats = {k: material(k, c) for k, c in COLORS.items() if k in ("equipment", "pipe", "boundary", "arrow")}
    mats["text"] = material("text", COLORS["text"], 1.0)
    mats["leader"] = material("leader", COLORS["leader"], 0.8)
    for k in ("plate", "loto_plate"):
        mats[k] = material(k, COLORS[k], 0.0, 1.0)
    target = bpy.data.objects.new("tour_target", None)
    link(target)
    cam = bpy.data.objects.new("tour_camera", bpy.data.cameras.new("tour_camera"))
    cam.data.lens = SCENE["camera_lens_mm"]
    cam.data.sensor_width = SCENE["camera_sensor_mm"]
    cam.data.sensor_fit = "HORIZONTAL"
    cam.data.clip_end = 1000.0
    link(cam)
    look = cam.constraints.new("TRACK_TO")
    look.target, look.track_axis, look.up_axis = target, "TRACK_NEGATIVE_Z", "UP_Y"
    scene.camera = cam
    xs = [e["position"][0] for e in SCENE["equipment"]] + [b["position"][0] for b in SCENE["boundaries"]]
    ys = [e["position"][1] for e in SCENE["equipment"]] + [b["position"][1] for b in SCENE["boundaries"]]
    cx, cy = (min(xs) + max(xs)) / 2, (min(ys) + max(ys)) / 2
    w, d = max(xs) - min(xs) + 12, max(ys) - min(ys) + 12
    ground = box("ground", (w + (0 if LEGACY else 30), d + (0 if LEGACY else 30), 0.05), (cx, cy, -0.03))
    ground.data.materials.append(material("ground_legacy", COLORS["ground"]) if LEGACY else ground_material())
    ground_note = text("disclaimer", "PROTOTYPE: placeholder geometry from the 2D seed layout. Not plant layout, sizes "
                       "or elevations.", (cx, min(ys) - 4.5, 0.02), 0.55, mats["text"])
    marker_mats, marker_objs, bl_objs, bands_objs = {}, {}, {}, {}
    if LEGACY:
        for e in SCENE["equipment"]:
            build_equipment_legacy(e, mats["equipment"])
            for o in [o for o in bpy.data.objects if o.name.startswith(e["id"] + "_")]:
                o["asset"], o["geometry"] = e["id"], e["geometry_status"]
        for p in SCENE["pipes"]:
            build_pipe_legacy(p, mats["pipe"], mats["arrow"])
    else:
        for e in SCENE["equipment"]:
            build_equipment_v2(e)
        for p in SCENE["pipes"]:
            build_pipe_v2(p)
        for u in SCENE.get("utilities", []):
            build_utility(u)
        for v in SCENE.get("valves", []):
            build_valve(v)
        for b in SCENE.get("level_bands", []):
            ring = cylinder("band_" + b["tag"], b["radius"] + 0.03, 0.16, (0, 0, b["z"]), vertices=48)
            e = next(x for x in SCENE["equipment"] if x["id"] == b["unit"])
            ring.location = (e["position"][0], e["position"][1], b["z"])
            ring.data.materials.append(material("band_" + b["tag"], COLORS["band"], 1.5, 0.5, 0.55))
            ring.visible_shadow = False
            bands_objs[b["tag"]] = ring
    for b in SCENE["boundaries"]:
        post = cylinder(b["id"], 0.18, 1.0, (b["position"][0], b["position"][1], 0.5), mat=mats["boundary"])
        if not LEGACY:
            register(post, "bl:" + b["stream"], "boundary", COLORS["boundary"])
        bl_objs[b["stream"]] = post
    for m in SCENE["markers"]:
        mat = material("marker_" + m["tag"], COLORS["normal"] if m["connected"] else COLORS["not_connected"], 0.4)
        marker_mats[m["tag"]] = (mat, m["connected"])
        ball = sphere("marker_" + m["tag"], 0.12 if LEGACY else 0.14, tuple(m["position"]), mat)
        ball.visible_shadow = False
        ball["tag"], ball["placement_basis"], ball["connected"] = m["tag"], m["placement_basis"], m["connected"]
        marker_objs[m["tag"]] = ball
    for spec in SCENE["labels"]:
        make_label(spec, cam, mats)
    sun = bpy.data.objects.new("sun", bpy.data.lights.new("sun", "SUN"))
    sun.data.energy, sun.rotation_euler = (3.0, (math.radians(50), math.radians(10), math.radians(35))) if LEGACY else \
        (3.2, (math.radians(42), math.radians(8), math.radians(-35)))
    if not LEGACY:
        sun.data.angle = math.radians(10)   # soft shadows
    link(sun)
    world = bpy.data.worlds.new("world")
    world.color = (0.12, 0.13, 0.15)
    scene.world = world
    try:
        world.use_nodes = True
        world.node_tree.nodes["Background"].inputs["Color"].default_value = (0.12, 0.13, 0.15, 1) if LEGACY else \
            (0.15, 0.16, 0.18, 1)
        world.node_tree.nodes["Background"].inputs["Strength"].default_value = 0.8 if LEGACY else 1.0
    except Exception:
        pass
    for engine in ("BLENDER_EEVEE", "BLENDER_EEVEE_NEXT", "BLENDER_WORKBENCH"):
        try:
            scene.render.engine = engine
            break
        except Exception:
            continue
    if not LEGACY:
        try:
            scene.view_settings.view_transform = "Standard"   # keep text, plates and service colours crisp
        except Exception:
            pass
    if "--gltf" in argv:
        for L in LABELS.values():
            for o in parts(L):
                show(o, False)
        bpy.ops.export_scene.gltf(filepath=os.path.join(out, "te_scene.glb"), export_format="GLB",
                                  export_extras=True, export_cameras=False, export_lights=False)
        print("EXPORTED", os.path.join(out, "te_scene.glb"))
    if not LEGACY:
        show(ground_note, False)

    still_w, still_h = SCENE["still_resolution"]
    scene.render.resolution_x, scene.render.resolution_y = still_w, still_h
    scene.render.resolution_percentage = 100
    half_w = 3.0 * (SCENE["camera_sensor_mm"] / 2.0) / SCENE["camera_lens_mm"]

    # ------------------------------------------------------------ 2D overlays (camera-fixed)
    OVERLAYS = {}
    if LEGACY:
        caption = text("caption", "", (-1.85, -0.74, -3.0), 0.055, mats["text"], align="LEFT")
        caption.parent = cam
    else:
        caption = None

    def cam_units(px):
        half_h = half_w * scene.render.resolution_y / scene.render.resolution_x
        return px * 2 * half_h / scene.render.resolution_y

    def overlay_obj(oid):
        if oid not in OVERLAYS:
            t = text("ov_" + oid, "", (0, 0, -3.0), 0.1, mats["text"], align="LEFT", align_y="TOP")
            t.parent = cam
            pl = bpy.data.objects.new("ovplate_" + oid, rounded_rect_mesh("ovplate_" + oid, 0, 0, 1, 1, 0))
            link(pl)
            pl.data.materials.append(mats["plate"])
            pl.parent = cam
            pl.visible_shadow = False
            OVERLAYS[oid] = {"text": t, "plate": pl, "swatches": []}
        return OVERLAYS[oid]

    def text_bbox(obj):
        bpy.context.view_layer.update()
        ev = obj.evaluated_get(bpy.context.evaluated_depsgraph_get())
        xs_, ys_ = [c[0] for c in ev.bound_box], [c[1] for c in ev.bound_box]
        sx = obj.scale[0]
        return (min(xs_) * sx, min(ys_) * sx, max(xs_) * sx, max(ys_) * sx)

    def layout_overlays(shot):
        """Corner badge, cards, legend and a two-line caption bar, each on a rounded dark plate."""
        W, H = scene.render.resolution_x, scene.render.resolution_y
        half_h = half_w * H / W
        m, pad, gap = cam_units(22), cam_units(12), cam_units(10)
        for o in OVERLAYS.values():
            for x in [o["text"], o["plate"]] + o["swatches"]:
                show(x, False)
        boxes = {}
        specs = {o["id"]: o for o in shot.get("overlays", [])}
        order = sorted(specs.values(), key=lambda o: ["caption", "badge", "card", "legend"].index(o["kind"]))
        caption_top = -half_h
        for o in order:
            ov = overlay_obj(o["id"])
            t = ov["text"]
            kind = o["kind"]
            size = cam_units(OVERLAY_EM_PX[kind])
            t.data.size = size
            if kind == "legend":
                t.data.body = "\n".join([o["title"]] + [r["text"] for r in o["rows"]])
            else:
                t.data.body = o["text"]
            corner = o.get("corner", "bottom_left")
            t.data.align_x = "LEFT"
            t.data.align_y = "TOP"
            t.location = (0, 0, -3.0)
            show(t, True)          # hidden objects are not re-evaluated: measure only while visible
            b = text_bbox(t)
            tw, th = b[2] - b[0], b[3] - b[1]
            sw_space = (size * 0.9 + gap) if kind == "legend" else 0.0
            if kind == "caption":
                left, top = -half_w + m + pad, -half_h + m + pad + th
            elif corner == "top_left":
                left, top = -half_w + m + pad, half_h - m - pad
            elif corner == "top_right":
                left, top = half_w - m - pad - tw, half_h - m - pad
            elif corner == "top_right_below":
                below = boxes.get("overlay:badge", (0, half_h - m, 0, half_h - m))[1]
                left, top = half_w - m - pad - tw, below - gap - pad
            else:   # bottom_right, above the caption bar
                left, top = half_w - m - pad - tw, caption_top + gap + pad + th
            t.location = (left - b[0], top - b[3], -3.0)
            x0, y0, x1, y1 = left - pad - sw_space, top - th - pad, left + tw + pad, top + pad
            if kind == "caption":
                x0, x1 = -half_w - 0.01, half_w + 0.01
                y0 = -half_h - 0.01
                caption_top = y1
            new = rounded_rect_mesh("ovplate_" + o["id"], x0, y0, x1, y1, 0.0 if kind == "caption" else pad * 0.9, -3.01)
            ov["plate"].data = new
            new.materials.append(mats["plate"])
            show(t, True)
            show(ov["plate"], True)
            boxes[o["id"]] = (x0, y0, x1, y1)
            if kind == "legend":
                lines = 1 + len(o["rows"])
                pitch = th / lines
                for k, row in enumerate(o["rows"]):
                    if k >= len(ov["swatches"]):
                        sw = bpy.data.objects.new("ovsw_%s_%d" % (o["id"], k), rounded_rect_mesh("sw", 0, 0, 1, 1, 0))
                        link(sw)
                        sw.parent = cam
                        ov["swatches"].append(sw)
                    sw = ov["swatches"][k]
                    key, name = row["swatch"].split(":", 1)
                    col = SERVICE_COLORS.get(name) if key == "service" else STATE_COLORS.get(name)
                    sw.data = rounded_rect_mesh("sw", 0, 0, size * 0.9, size * 0.42, size * 0.21, -3.005)
                    sw.data.materials.clear()
                    swm = material("swatch_" + name, (0, 0, 0, 1), 0.0, 1.0)   # pure emission = the exact service colour
                    bsdf = swm.node_tree.nodes.get("Principled BSDF")
                    bsdf.inputs["Emission Color"].default_value = col or (1, 1, 1, 1)
                    bsdf.inputs["Emission Strength"].default_value = 1.0
                    sw.data.materials.append(swm)
                    yc = top - pitch * (k + 1.5)
                    sw.location = (left - sw_space + gap * 0.3, yc - size * 0.21, 0)
                    show(sw, True)
        return boxes

    def apply_states(index, frame=None):
        states = SCENE["replay_states"][index]["states"] if SCENE["replay_states"] else {}
        for tag, (mat, connected) in marker_mats.items():
            set_color(mat, COLORS[states.get(tag, "normal" if connected else "not_connected")], frame)

    def px_of(p):
        co = world_to_camera_view(scene, cam, Vector(p))
        return co.x * scene.render.resolution_x, (1.0 - co.y) * scene.render.resolution_y, co.z

    GHOSTED = set()

    def apply_focus(shot):
        """Focus unit full colour; everything else ghosted at 25%; utilities, chevrons and highlights per shot."""
        GHOSTED.clear()
        focus = shot.get("focus")
        pipes = {p["id"]: p for p in SCENE["pipes"]}
        utils = {u["id"]: u for u in SCENE.get("utilities", [])}
        valves = {v["tag"]: v for v in SCENE.get("valves", [])}
        hl = set(shot.get("highlight", []))
        util_mode = shot.get("utilities", [])
        for obj, grp, key, color, emit in REGISTRY:
            kind, _, ident = grp.partition(":")
            visible, variant = True, "normal"
            if kind == "unit":
                variant = "ghost" if (focus and ident != focus) or shot.get("ghost_all") else "normal"
            elif kind in ("pipe", "chev") and ident in pipes:
                p = pipes[ident]
                touches = focus in (p["from"], p["to"])
                variant = "ghost" if (focus and not touches) or shot.get("ghost_all") else "normal"
                if kind == "chev":
                    visible = shot.get("chevrons", True) and variant != "ghost"
                if variant == "normal" and focus and (("recycle" in hl and p["service"] == "recycle") or (
                        "vapour_outlet" in hl and p["from"] == focus and p["service"] in ("recycle", "purge", "gas_feed"))):
                    variant = "glow"
            elif kind in ("util", "chev") and ident in utils:
                u = utils[ident]
                visible = util_mode == "all" or (util_mode == "focus" and u["unit"] == focus)
                if kind == "chev":
                    visible = visible and shot.get("chevrons", True)
                if visible and focus and (("cooling_water" in hl and u["service"].startswith("cooling_water")) or
                                          ("steam" in hl and u["service"] == "steam")):
                    variant = "glow"
            elif kind == "valve":
                v = valves[ident]
                on_kind, _, on_id = v["on"].partition(":")
                if on_kind == "utility":
                    visible = util_mode == "all" or (util_mode == "focus" and utils[on_id]["unit"] == focus)
                else:
                    p = pipes[on_id]
                    variant = "ghost" if (focus and focus not in (p["from"], p["to"])) or shot.get("ghost_all") else "normal"
                if visible and variant == "normal" and "valves" in hl and v["unit"] == focus:
                    variant = "glow"
            elif kind == "bl":
                p = pipes[ident]
                variant = "ghost" if (focus and focus not in (p["from"], p["to"])) else "normal"
            show(obj, visible)
            obj.data.materials.clear()
            obj.data.materials.append(mat_for(key, color, variant, emit))
            obj.visible_shadow = variant != "ghost"
            if variant == "ghost" or not visible:
                GHOSTED.add(obj.name)
        shown = set(shot.get("markers", []))
        for tag, ball in marker_objs.items():
            show(ball, tag in shown)
        for tag, ring in bands_objs.items():
            show(ring, tag in shot.get("level_bands", []))

    def first_hit(origin, dest, ignore):
        """(object name, distance) of the first opaque hit from origin toward dest, skipping ignored/hidden/ghosted."""
        dg = bpy.context.evaluated_depsgraph_get()
        vec = dest - origin
        dist, direction = vec.length, vec.normalized()
        o, travelled = origin.copy(), 0.0
        for _ in range(64):
            hit, loc, _n, _i, obj, _m = scene.ray_cast(dg, o, direction, distance=max(1e-4, dist - travelled))
            if not hit:
                return None
            step = (loc - o).length
            name = obj.name if obj is not None else ""
            src = bpy.data.objects.get(name)
            if name in ignore or name in GHOSTED or (src is not None and src.hide_render) or name.startswith(("ov", "plate_", "label_")):
                o, travelled = loc + direction * 1e-3, travelled + step + 1e-3
                continue
            return name, travelled + step
        return None

    def screen_box(obj, dg):
        ev = obj.evaluated_get(dg)
        mw = ev.matrix_world
        pts = [px_of(mw @ Vector(c)) for c in ev.bound_box]
        return [min(p[0] for p in pts), min(p[1] for p in pts), max(p[0] for p in pts), max(p[1] for p in pts)], \
            all(p[2] > 0 for p in pts)

    def focus_rects(shot, dg):
        if not shot.get("focus"):
            return []
        out = []
        for obj, grp, key, color, emit in REGISTRY:
            if grp == "unit:" + shot["focus"] and not obj.hide_render:
                b, front = screen_box(obj, dg)
                if front:
                    out.append(b)
        return out

    def overlay_rects(boxes):
        """Camera-space overlay plates -> pixel rects."""
        W, H = scene.render.resolution_x, scene.render.resolution_y
        half_h = half_w * H / W
        return {k: [(x0 + half_w) / (2 * half_w) * W, (half_h - y1) / (2 * half_h) * H,
                    (x1 + half_w) / (2 * half_w) * W, (half_h - y0) / (2 * half_h) * H] for k, (x0, y0, x1, y1) in boxes.items()}

    def layout_shot(shot, ov_boxes):
        """Pills: fixed on-screen size, placed greedily around each anchor outside the focus silhouette, the
        overlays and every visible marker; a short leader joins pill and anchor."""
        vl = bpy.context.view_layer
        vl.update()
        dg = bpy.context.evaluated_depsgraph_get()
        W, H = scene.render.resolution_x, scene.render.resolution_y
        mw = cam.matrix_world
        cam_loc = mw.translation.copy()
        right = mw.col[0].xyz.normalized()
        up = mw.col[1].xyz.normalized()
        items, info = [], {}
        for lid in shot["visible"]:
            L = LABELS[lid]
            a = Vector(L["spec"]["anchor"])
            ax, ay, depth = px_of(a)
            if depth <= 0.1 or not (0 <= ax <= W and 0 <= ay <= H):
                for o in parts(L):
                    show(o, False)
                continue
            bx, by, _ = px_of(a + right)
            ppm = math.hypot(bx - ax, by - ay)
            ev = L["obj"].evaluated_get(dg)
            xs_, ys_ = [c[0] for c in ev.bound_box], [c[1] for c in ev.bound_box]
            w0, h0 = max(xs_) - min(xs_), max(ys_) - min(ys_)
            cx0, cy0 = (max(xs_) + min(xs_)) / 2, (max(ys_) + min(ys_)) / 2
            em_px = EM_PX.get(L["spec"]["kind"], 22.0) * H / 1080.0
            s = em_px / ppm if ppm > 0 else 0.1
            pad = 0.32 * em_px
            items.append({"id": lid, "anchor": (ax, ay), "w": w0 * s * ppm + 2 * pad + h0 * s * ppm * 0.4,
                          "h": h0 * s * ppm + 2 * pad})
            info[lid] = (a, ax, ay, ppm, s, w0, h0, cx0, cy0, pad)
        obstacles = list(overlay_rects(ov_boxes).values())
        obstacles += [[r[0] - 6, r[1] - 6, r[2] + 6, r[3] + 6] for r in focus_rects(shot, dg)]
        for m in marker_objs.values():
            if m.hide_render:
                continue
            mx, my, mz = px_of(m.location)
            if mz > 0 and -20 <= mx <= W + 20 and -20 <= my <= H + 20:
                obstacles.append((mx - 10, my - 10, mx + 10, my + 10))
        # Units first, then tags in shot order: priority = order of appearance.
        items.sort(key=lambda it: 0 if it["id"].startswith("unit:") else 1)
        placed = place_labels(items, W, H, obstacles, margin=14.0 * H / 1080, gap=8.0 * H / 1080,
                              max_radius=0.34 * H if shot.get("focus") else 0.30 * H)  # 0.22 before the larger label font
        for lid, r in placed.items():
            a, ax, ay, ppm, s, w0, h0, cx0, cy0, pad = info[lid]
            L = LABELS[lid]
            ccx, ccy = r["center"]
            plane_pt = a + right * ((ccx - ax) / ppm) + up * (-(ccy - ay) / ppm)
            pos = cam_loc + (plane_pt - cam_loc) * LABEL_DEPTH
            k = s * LABEL_DEPTH
            L["obj"].scale = (k, k, k)
            L["obj"].location = pos - (right * cx0 + up * cy0) * k
            pad_local = pad / (ppm * s)
            hh = h0 / 2 + pad_local
            hw = w0 / 2 + pad_local + hh * 0.4
            L["plate"].data = rounded_rect_mesh("plate_" + lid, cx0 - hw, cy0 - hh, cx0 + hw, cy0 + hh, hh, -0.05)
            L["plate"].data.materials.append(mats["loto_plate"] if L["spec"]["kind"] == "loto" else mats["plate"])
            L["plate"].location = (0, 0, 0)
            L["plate"].scale = (1, 1, 1)
            for o in parts(L):
                show(o, True)
            bx0, by0, bx1, by1 = r["box"]
            ex, ey = min(max(ax, bx0), bx1), min(max(ay, by0), by1)
            if math.hypot(ex - ax, ey - ay) < 6.0 * H / 1080:
                show(L["leader"], False)
            else:
                e_plane = a + right * ((ex - ax) / ppm) + up * (-(ey - ay) / ppm)
                e_world = cam_loc + (e_plane - cam_loc) * LABEL_DEPTH
                vec = e_world - a
                L["leader"].location = a + vec / 2
                L["leader"].rotation_quaternion = vec.to_track_quat("Z", "Y")
                radius = 1.2 * H / 1080 / ppm
                L["leader"].scale = (radius, radius, vec.length)
        return {lid: {"box": r["box"], "cost": r["cost"]} for lid, r in placed.items()}

    def layout_legacy(shot):
        caption.data.body = shot["caption"]
        return {}

    def choose_view(shot):
        """Among the fitted candidate cameras, the first that hides the fewest of the shot's markers (raycast)."""
        cands = shot.get("camera_candidates") or [{"camera": shot["camera"], "target": shot["target"]}]
        if not REAL or len(cands) == 1:
            return cands[0], None
        tags = [t for t in shot.get("markers", []) if t in marker_objs] if not LEGACY else \
            [LABELS[l]["spec"]["marker"] for l in shot["visible"] if LABELS[l]["spec"].get("marker")]
        best = None
        for k, c in enumerate(cands):
            cam.location, target.location = c["camera"], c["target"]
            bpy.context.view_layer.update()
            cam_loc = cam.matrix_world.translation.copy()
            hidden = []
            for tag in tags:
                m = marker_objs[tag]
                hit = first_hit(cam_loc, m.location.copy(), set())
                if hit and hit[0] != m.name and hit[1] < (m.location - cam_loc).length - 0.15:
                    hidden.append(tag)
            if best is None or len(hidden) < len(best[1]):
                best = (k, hidden)
            if not hidden:
                break
        return cands[best[0]], {"chosen": best[0], "of": len(cands), "hidden_markers": best[1]}

    def apply_shot(shot):
        for L in LABELS.values():
            for o in parts(L):
                show(o, False)
        if not LEGACY:
            apply_focus(shot)
        view, choice = choose_view(shot)
        shot["_view"] = choice
        cam.location, target.location = view["camera"], view["target"]
        if SCENE["replay_states"]:
            apply_states(shot["state_index"])
        visible = set(shot["visible"])
        for lid, L in LABELS.items():
            body = shot.get("bodies", {}).get(lid)
            L["obj"].data.body = body if body is not None else (L["spec"].get("legacy_body", L["spec"]["body"]) if LEGACY
                                                                else L["spec"]["body"])
            for o in parts(L):
                show(o, lid in visible)
        if LEGACY:
            return layout_legacy(shot), {}
        if not REAL:
            return {}, {}
        ov_boxes = layout_overlays(shot)
        return layout_shot(shot, ov_boxes), ov_boxes

    def measure(shot, png, ov_boxes):
        """What a viewer sees: 2D boxes of labels and overlays, occlusion by raycast, focus silhouette rects, marker
        positions, and WCAG contrast of each text box measured from the rendered pixels."""
        bpy.context.view_layer.update()
        dg = bpy.context.evaluated_depsgraph_get()
        W, H = scene.render.resolution_x, scene.render.resolution_y
        cam_loc = cam.matrix_world.translation.copy()
        label_parts = {o.name for L in LABELS.values() for o in parts(L)}
        leaders = {L["leader"].name for L in LABELS.values() if L["leader"] is not None}
        entries = []
        for lid in shot["visible"]:
            L = LABELS[lid]
            if L["obj"].hide_render:
                entries.append({"id": lid, "kind": L["spec"]["kind"], "shown": False, "reason": "anchor out of view"})
                continue
            tb, in_front = screen_box(L["obj"], dg)
            pb = screen_box(L["plate"], dg)[0] if L["plate"] is not None and not L["plate"].hide_render else None
            ax, ay, az = px_of(L["spec"]["anchor"])
            own = {o.name for o in parts(L)}
            ev = L["obj"].evaluated_get(dg)
            bx = [c[0] for c in ev.bound_box]
            by = [c[1] for c in ev.bound_box]
            hits, samples = set(), 0
            for i in range(7):
                for j in range(3):
                    lp = Vector((min(bx) + (max(bx) - min(bx)) * (i + 0.5) / 7, min(by) + (max(by) - min(by)) * (j + 0.5) / 3, 0.0))
                    wp = ev.matrix_world @ lp
                    samples += 1
                    hit = first_hit(cam_loc, wp, label_parts)
                    if hit and hit[1] < (wp - cam_loc).length - 0.05:
                        hits.add((i, j, hit[0]))
            occluders = sorted({h[2] for h in hits})
            e = {"id": lid, "kind": L["spec"]["kind"], "shown": True, "text": L["obj"].data.body,
                 "lines": L["obj"].data.body.count("\n") + 1, "text_box": tb, "plate_box": pb,
                 "in_front": in_front, "anchor_px": [ax, ay], "anchor_on_screen": az > 0 and 0 <= ax <= W and 0 <= ay <= H,
                 "label_occluded_fraction": round(len(hits) / samples, 3),
                 "label_occluded_by": ", ".join(occluders) if occluders else None}
            tag = L["spec"].get("marker")
            if tag:
                mloc = marker_objs[tag].location.copy()
                hit = first_hit(cam_loc, mloc, own | leaders)
                mdist = (mloc - cam_loc).length
                e["marker"] = tag
                e["marker_occluded_by"] = hit[0] if hit and hit[0] != marker_objs[tag].name and hit[1] < mdist - 0.15 else None
            entries.append(e)
        if LEGACY:
            cb, cf = screen_box(caption, dg)
            entries.append({"id": "caption", "kind": "caption", "shown": True, "text": caption.data.body,
                            "lines": caption.data.body.count("\n") + 1, "text_box": cb, "in_front": cf, "plate_box": None,
                            "label_occluded_by": None})
        else:
            rects = overlay_rects(ov_boxes)
            for o in shot.get("overlays", []):
                ov = OVERLAYS[o["id"]]
                tb, tf = screen_box(ov["text"], dg)
                entries.append({"id": o["id"], "kind": "overlay_" + o["kind"], "shown": True, "text": ov["text"].data.body,
                                "lines": ov["text"].data.body.count("\n") + 1, "text_box": tb, "in_front": tf,
                                "plate_box": rects[o["id"]], "label_occluded_by": None})
        markers_px = {}
        for tag, m in marker_objs.items():
            if m.hide_render:
                continue
            mx, my, mz = px_of(m.location)
            if mz > 0 and 0 <= mx <= W and 0 <= my <= H:
                markers_px[tag] = [round(mx, 1), round(my, 1)]
        try:
            import numpy as np
            img = bpy.data.images.load(png, check_existing=False)
            buf = np.empty(img.size[0] * img.size[1] * 4, dtype=np.float32)
            img.pixels.foreach_get(buf)
            rgb = buf.reshape(img.size[1], img.size[0], 4)[::-1, :, :3]
            lin = np.where(rgb <= 0.04045, rgb / 12.92, ((rgb + 0.055) / 1.055) ** 2.4)
            lum = lin[..., 0] * 0.2126 + lin[..., 1] * 0.7152 + lin[..., 2] * 0.0722
            for e in entries:
                if not e.get("shown"):
                    continue
                x0, y0, x1, y1 = e["text_box"]
                xi0, yi0 = max(0, int(math.floor(x0))), max(0, int(math.floor(y0)))
                xi1, yi1 = min(W, int(math.ceil(x1))), min(H, int(math.ceil(y1)))
                if xi1 - xi0 < 2 or yi1 - yi0 < 2:
                    e["contrast"] = None
                    continue
                v = lum[yi0:yi1, xi0:xi1].ravel()
                bg, light, dark = float(np.median(v)), float(np.percentile(v, 97)), float(np.percentile(v, 3))
                up_r, down_r = contrast_ratio(light, bg), contrast_ratio(dark, bg)
                e["contrast"] = {"background": bg, "text": light if up_r >= down_r else dark,
                                 "ratio": max(up_r, down_r), "method": "median vs 97th/3rd percentile luminance in text box"}
            bpy.data.images.remove(img)
        except Exception as exc:
            for e in entries:
                e.setdefault("contrast", None)
            print("CONTRAST UNAVAILABLE", exc)
        return entries, markers_px, focus_rects(shot, dg)

    report = {"resolution": [still_w, still_h], "label_layout": SCENE.get("label_layout", "declutter"),
              "em_px_targets_1080": LEGACY_EM if LEGACY else EM_PX,
              "overlay_em_px_1080": {} if LEGACY else OVERLAY_EM_PX, "stills": []}
    for shot in SCENE["shots"]:
        placement, ov_boxes = apply_shot(shot)
        scene.render.filepath = os.path.join(out, shot["name"] + ".png")
        bpy.ops.render.render(write_still=True)
        print("RENDERED", scene.render.filepath)
        if REAL:
            labels, markers_px, rects = measure(shot, scene.render.filepath, ov_boxes)
            report["stills"].append({"name": shot["name"], "image": shot["name"] + ".png", "visible": shot["visible"]
                                     + [o["id"] for o in shot.get("overlays", [])], "focus": shot.get("focus"),
                                     "view_choice": shot.get("_view"), "labels": labels, "markers_px": markers_px,
                                     "focus_rects": rects,
                                     "placement_cost": {k: v["cost"] for k, v in placement.items()}})
    if REAL:
        with open(os.path.join(out, "label_boxes.json"), "w", encoding="utf-8") as f:
            json.dump(report, f, indent=1)
        print("MEASURED", os.path.join(out, "label_boxes.json"))
    if not animation:
        return
    # Narrated video (not rendered in this review round): camera keys per segment with eased (Bezier) moves,
    # labels/overlays laid out per hold. Animated chevron offset is designed, not built (docs/3D_TOUR_PLAN.md).
    video = SCENE["video"]
    scene.render.resolution_x, scene.render.resolution_y = video["width"], video["height"]
    scene.render.fps = video["fps"]
    fps = video["fps"]
    segments = SCENE.get("timeline") or []
    frame_of = lambda t: int(round(t * fps)) + 1  # noqa: E731
    for seg in segments:
        seg["_f"] = (frame_of(seg["start"]), frame_of(seg["hold"]), frame_of(seg["end"]))
    try:
        bpy.context.preferences.edit.keyframe_new_interpolation_type = "BEZIER"
    except Exception:
        pass
    for seg in segments:
        f0, f1, f2 = seg["_f"]
        apply_shot(seg)
        for f in (f1, f2):
            cam.keyframe_insert("location", frame=f)
            target.keyframe_insert("location", frame=f)
    scene.frame_start, scene.frame_end = 1, (segments[-1]["_f"][2] if segments else 1)
    try:
        scene.render.image_settings.media_type = "VIDEO"
    except Exception:
        pass
    try:
        scene.render.image_settings.file_format = "FFMPEG"
        scene.render.ffmpeg.format, scene.render.ffmpeg.codec = "MPEG4", "H264"
        scene.render.filepath = os.path.join(out, "orientation_tour_silent.mp4")
    except Exception:
        scene.render.image_settings.file_format = "PNG"
        scene.render.filepath = os.path.join(out, "walkthrough_frames", "frame_")
    bpy.ops.render.render(animation=True)
    print("RENDERED", scene.render.filepath)


main(sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else [])
